    "script": "%dw 2.0\r\noutput application/json\r\n---\r\npayload\r\n    filter $.status == \"active\"\r\n    map (item) -> ({\r\n        id: item.id,\r\n        name: upper(item.name),\r\n        score: item.score\r\n    })"
