    "description": "Parse and generate Server-Sent Events (SSE) using the native text/event-stream format introduced in DataWeave 2.9. Handles real-time streaming responses from AI/LLM APIs, live dashboards, and push notifications.",
    "inputMime": "application/json",
    "input": "{\r\n  \"events\": [\r\n    \"data: {\\\"token\\\": \\\"Hello\\\"}\",\r\n    \"data: {\\\"token\\\": \\\" world\\\"}\",\r\n    \"data: {\\\"token\\\": \\\"!\\\"}\",\r\n    \"data: [DONE]\"\r\n  ]\r\n}\r",
    "outputMime": "application/json",
